/* yeni vakalar depodan iner: vakalar/index.json + vaka-XX.json (güncelleme gerekmez) */
const CASES_URL = "https://raw.githubusercontent.com/bolatemre/sistem-acigi/main/vakalar/";
const CASES_KEY = "dedektif-vakalar";
const validCase = d => !!(d && d.id && d.title && Array.isArray(d.locations) && d.locations.length && Array.isArray(d.suspects) && d.suspects.length >= 2 && Array.isArray(d.clues) && d.suspects.some(x => x.id === d.culprit));
function addCases(list){ let n = 0; (list || []).forEach(d => { if (validCase(d) && !STORY_CASES.some(x => x.id === d.id)){ STORY_CASES.push(d); n++; } }); return n; }
function cachedCases(){ try { const a = JSON.parse(localStorage.getItem(CASES_KEY) || "[]"); return Array.isArray(a) ? a : []; } catch { return []; } }
async function loadRemoteCases(){
  if (!STORY_MODE) return;
  addCases(cachedCases());
  try {
    const get = async f => { const r = await fetch(CASES_URL + f + "?t=" + Date.now(), {cache:"no-store"}); if (!r.ok) throw new Error(f); return r.json(); };
    const idx = await get("index.json");
    const list = (idx && Array.isArray(idx.files) ? idx.files : []).filter(e => e && e.id && /^vaka-\d+\.json$/.test(e.file || ""));
    const fresh = [];
    for (const e of list){
      if (STORY_CASES.some(x => x.id === e.id)) continue;
      try { const d = await get(e.file); if (validCase(d) && d.id === e.id) fresh.push(d); } catch {}
    }
    if (!fresh.length) return;
    try { localStorage.setItem(CASES_KEY, JSON.stringify(cachedCases().concat(fresh))); } catch {}
    const n = addCases(fresh);
    if (n){ news(n === 1 ? "Masana yeni bir dosya ulaştı." : `Masana ${n} yeni dosya ulaştı.`); save(); render(); }
  } catch {}
}
